import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n];
        long[] b = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextLong();
            b[i] = sc.nextLong();
        }
        // dpA: 当前展板选A的最大值，dpB: 选B的最大值
        long dpA = a[0];
        long dpB = b[0];
        for (int i = 1; i < n; i++) {
            long newDpA = dpB + a[i];   // 前一块只能选B
            long newDpB = dpA + b[i];   // 前一块只能选A
            dpA = newDpA;
            dpB = newDpB;
        }
        long ans = Math.max(dpA, dpB);
        System.out.println(ans);
    }
}
